/*
 * Chart chrome borrows Gravity UI tokens (surface, ink, grid), so it follows the
 * app theme automatically. Series colours are the validated categorical slots
 * 1–3, stepped separately for each theme (see data-theme below).
 */
.line-chart {
  --lc-surface: var(--g-color-base-background);
  --lc-ink: var(--g-color-text-primary);
  --lc-ink-2: var(--g-color-text-secondary);
  --lc-ink-muted: var(--g-color-text-hint);
  --lc-grid: var(--g-color-line-generic);
  --lc-axis: var(--g-color-line-generic-hover);

  --lc-series-1: #2a78d6;
  --lc-series-2: #eb6834;
  --lc-series-3: #1baf7a;

  position: relative;
  color: var(--lc-ink);
  font-family: var(--g-font-family-sans, system-ui, sans-serif);
}

.line-chart[data-theme='dark'] {
  --lc-series-1: #3987e5;
  --lc-series-2: #d95926;
  --lc-series-3: #199e70;
}

.line-chart__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}

.line-chart__title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}

.line-chart__subtitle {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--lc-ink-2);
}

.line-chart__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
  font-size: 13px;
  color: var(--lc-ink-2);
}

.line-chart__legend li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.line-chart__key {
  width: 16px;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
}

.line-chart__plot {
  position: relative;
}

.line-chart svg {
  display: block;
  width: 100%;
  overflow: visible;
  outline: none;
}

.line-chart svg:focus-visible {
  outline: 2px solid var(--g-color-line-focus, var(--lc-ink-2));
  outline-offset: 2px;
  border-radius: 4px;
}

.line-chart__grid {
  stroke: var(--lc-grid);
  stroke-width: 1;
}

.line-chart__baseline {
  stroke: var(--lc-axis);
  stroke-width: 1;
}

.line-chart__tick {
  fill: var(--lc-ink-muted);
  font-size: 12px;
}

.line-chart__end-label {
  fill: var(--lc-ink-2);
  font-size: 12px;
  font-weight: 600;
}

.line-chart__crosshair {
  stroke: var(--lc-axis);
  stroke-width: 1;
}

.line-chart__line {
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.line-chart__dot {
  stroke: var(--lc-surface);
  stroke-width: 2;
}

.line-chart__tooltip {
  position: absolute;
  top: 0;
  z-index: 1;
  min-width: 150px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--g-color-base-float, var(--lc-surface));
  box-shadow:
    0 0 0 1px var(--lc-grid),
    0 4px 16px rgba(0, 0, 0, 0.16);
  font-size: 12px;
  pointer-events: none;
}

.line-chart__tooltip-title {
  margin-bottom: 4px;
  color: var(--lc-ink-2);
}

.line-chart__tooltip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  line-height: 20px;
}

.line-chart__tooltip-value {
  margin-left: auto;
  padding-left: 12px;
  color: var(--lc-ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.line-chart__tooltip-name {
  color: var(--lc-ink-2);
}

.line-chart__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.line-chart__table th,
.line-chart__table td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--lc-grid);
  text-align: right;
}

.line-chart__table th:first-child,
.line-chart__table td:first-child {
  text-align: left;
}

.line-chart__table th {
  color: var(--lc-ink-2);
  font-weight: 500;
}

