              <SegmentedRadioGroup.Option value="dark">Тёмная</SegmentedRadioGroup.Option>
            </SegmentedRadioGroup>
          </div>
          <LineChart
            title="Визиты по каналам"
            subtitle="Тысяч визитов в месяц, 2026"
            categories={months}
            series={series}
          />
        </div>
      </div>
    </ThemeProvider>
  );
}

